from pathlib import Path
import base64, io, tarfile, zlib


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one match, found {count}")
    return text.replace(old, new, 1)

archive = zlib.decompress(base64.b64decode(''))
with tarfile.open(fileobj=io.BytesIO(archive), mode="r:") as tar:
    for member in tar.getmembers():
        path = Path(member.name)
        if path.exists():
            raise RuntimeError(f"refusing to overwrite existing scaffold file: {path}")
        path.parent.mkdir(parents=True, exist_ok=True)
        source = tar.extractfile(member)
        if source is None:
            raise RuntimeError(f"archive member has no file data: {member.name}")
        path.write_bytes(source.read())
        path.chmod(member.mode)

root = Path("Cargo.toml")
text = root.read_text(encoding="utf-8")
text = replace_once(text, '  "crates/neoethos-gpu-contracts",\n', '  "crates/neoethos-gpu-contracts",\n  "crates/neoethos-gpu-cuda",\n', "CUDA workspace member")
root.write_text(text, encoding="utf-8")

workflow = Path(".github/workflows/agent-stage1.yml")
text = workflow.read_text(encoding="utf-8")
text = replace_once(text, """      - name: Test search crate
""", """      - name: Test CUDA ABI scaffold
        shell: bash
        run: |
          set -o pipefail
          cargo test -p neoethos-gpu-cuda 2>&1 | tee /tmp/stage1-diagnostics/cuda-scaffold-test.log

      - name: Lint rented-GPU run kit
        shell: bash
        run: |
          set -o pipefail
          bash -n scripts/gpu-bench/preflight.sh scripts/gpu-bench/prepare_worktrees.sh
          python3 -m py_compile scripts/gpu-bench/run_matrix.py scripts/gpu-bench/collate.py

      - name: Test search crate
""", "CUDA and run-kit CI steps")
workflow.write_text(text, encoding="utf-8")
print("registered CUDA ABI scaffold and fail-fast rented-GPU run kit")
